Q: How to capture process-space key events in OSX command-line tool, CoreFoundation, C API? A: <p>Here is a bit of individual research that resulted in 120 lines of <em>MVCE</em>, which programmatically captures and possibly processes keyboard events from the Terminal,  running this command-line program. There is a block argument in dispatch_sync() function, which I don't particularly like, because it is a polluted C API (Apple specific extension to the C standard, AFAIK), but I haven't come upon an idea how to write that part in plain C elegantly, yet. The program compiles in gcc (macOS command-line tools) as well as in Xcode and runs in macOS 15.5, Arm64. More functional, interaction and possible issues and side-effect testing on this and other hardware and systems is under way...</p>
<p>Here's the code. I don't how much of a decent programming practice it may represent, yet I believe it is good to share it, at least for the reason that the question has not received a more straightforward answer so far:</p>
<pre><code>//  cfmn.c
//  gcc -Wall -o cfmn cfmn.c -framework ApplicationServices
//_______________________________________________________________________

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/types.h&gt;
#include &lt;ApplicationServices/ApplicationServices.h&gt;

static dispatch_queue_t  lock;
static CFMutableArrayRef events;

//_______________________________________________________________________

CGEventRef callback(CGEventTapProxy proxy,
                    CGEventType type,
                    CGEventRef event,
                    void *refcon)
{
    CGEventFlags f = CGEventGetFlags(event);
    // Exclude command or control modifiers
    if (((f &amp; kCGEventFlagMaskCommand) == 0)&amp;&amp;((f &amp; kCGEventFlagMaskControl) == 0)) {
       if (type == kCGEventKeyDown) {
          CGKeyCode keyCode = (CGKeyCode)CGEventGetIntegerValueField(event, kCGKeyboardEventKeycode);
          printf (&quot;Key code: %d\n&quot;, keyCode);
          if (keyCode == 53)
              CFRunLoopStop(CFRunLoopGetCurrent());
          // unelegant part of code ...
          dispatch_sync(lock, ^{
              CFArrayAppendValue(events, event);
          });
          ;
       }
       return NULL; // do not return event
   }
   return event;    // return event unmodified
}

//_______________________________________________________________________

int main(int argc, const char * argv[]) 
{

    CFArrayRef windowList;
    char appname[256] = {0};    
    pid_t frontmostPid = 0;
    void* userinfo = NULL;
    CFRunLoopSourceRef runLoopSource;

    lock = dispatch_queue_create(&quot;lock&quot;, NULL);
    events = CFArrayCreateMutable(kCFAllocatorDefault,
                                  0,
                                  &amp;kCFTypeArrayCallBacks);

    windowList = CGWindowListCopyWindowInfo(kCGWindowListOptionOnScreenOnly, 
                           kCGNullWindowID);

    if (windowList != NULL) {
        CFIndex count = CFArrayGetCount(windowList);
        for (CFIndex i = 0; i &lt; count; i++) {
            CFDictionaryRef windowInfo = CFArrayGetValueAtIndex(windowList, i);
            CFNumberRef layerNum = CFDictionaryGetValue(windowInfo,
                                                     kCGWindowLayer);
            int layer = 0;
            if (layerNum &amp;&amp; CFNumberGetValue(layerNum, kCFNumberIntType, &amp;layer) &amp;&amp; layer == 0) {
                CFNumberRef pidNum = CFDictionaryGetValue(windowInfo, kCGWindowOwnerPID);
                if (pidNum) {
                    CFNumberGetValue(pidNum, kCFNumberIntType, &amp;frontmostPid);
                }
                CFStringRef ownerName = CFDictionaryGetValue(windowInfo, kCGWindowOwnerName);
                if (ownerName) {
                    CFStringGetCString(ownerName,
                                    appname,
                                    sizeof(appname),
                                    kCFStringEncodingUTF8);
                 }
                 break;
              }
          }
          CFRelease(windowList);
      }

      printf(&quot;\n|- - - - - Main Loop Test - - - - -|\n&quot;);
      printf(&quot;|- - press any key; &lt;esc&gt;=quit- - -|\n&quot;);
      printf(&quot;Frontmost App: %s;  &quot;,appname);
      printf(&quot;PID: %d\n&quot;,     frontmostPid );

      CGEventMask eventMask = CGEventMaskBit(kCGEventKeyDown);

      CFMachPortRef eventPort = CGEventTapCreateForPid(frontmostPid,
                                              kCGHeadInsertEventTap,
                                              kCGEventTapOptionDefault,
                                              eventMask,
                                              callback,
                                              userinfo);
      if (eventPort == NULL) {
          fprintf(stderr, &quot;NULL event port\n&quot;);
          return 1;      
      }

      runLoopSource = CFMachPortCreateRunLoopSource(kCFAllocatorDefault, 
                                                    eventPort, 
                                                    0);
      CFRunLoopAddSource(CFRunLoopGetCurrent(), 
                         runLoopSource, 
                         kCFRunLoopCommonModes);
      CGEventTapEnable(eventPort, true);
      CFRunLoopRun();

      printf   (&quot;Program stopped\n\n&quot;);
      CFRelease(runLoopSource);
      CFRelease(eventPort);
      CFRelease(events);
      dispatch_release(lock);

   return 0;
}
</code></pre>
